import threading


def reproduce(connect, service) -> str | None:
    key = "repro-double-charge-key-1"
    account_id = 1
    amount = 10
    n = 16

    # Starting balance for the account under test.
    try:
        with connect() as conn:
            row = conn.execute(
                "SELECT balance FROM accounts WHERE id = %s", (account_id,)
            ).fetchone()
            balance_before = row[0] if row else None
    except Exception:
        balance_before = None

    barrier = threading.Barrier(n)
    lock = threading.Lock()
    results = []
    errors = []

    def worker():
        try:
            with connect() as conn:
                barrier.wait(timeout=15)
                try:
                    result = service.pay(conn, key, account_id, amount)
                except Exception as exc:  # expected exceptions are recorded, not escaped
                    with lock:
                        errors.append(repr(exc))
                    return
                with lock:
                    results.append(result)
        except Exception as exc:
            with lock:
                errors.append(repr(exc))

    threads = [threading.Thread(target=worker) for _ in range(n)]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=30)

    try:
        with connect() as conn:
            cnt = conn.execute(
                "SELECT COUNT(*) FROM payments WHERE idempotency_key = %s", (key,)
            ).fetchone()[0]
            row = conn.execute(
                "SELECT balance FROM accounts WHERE id = %s", (account_id,)
            ).fetchone()
            balance_after = row[0] if row else None
    except Exception as exc:
        return f"could not verify payment count for {key}: {exc!r}"

    true_count = sum(1 for r in results if r is True)

    if cnt > 1 or true_count > 1:
        return (
            f"payment {key} was charged {cnt} times "
            f"({true_count} calls returned True, payments rows={cnt}) for one idempotency key"
        )

    if balance_before is not None and balance_after is not None:
        deducted = balance_before - balance_after
        if cnt == 1 and deducted != amount:
            return (
                f"payment {key} recorded once but balance deducted {deducted} "
                f"instead of {amount}"
            )
        if cnt > 1:
            return f"payment {key} was charged {cnt} times"

    return None
